import { useClerk } from "@clerk/react";
import "./AdminLayout.css";

// Shared admin shell: navy sidebar + main area, matching the Figma "Admin / ..." frames.
// Pages that don't exist yet are listed so the nav matches the design.
const NAV_LINKS = [
    { label: "Dashboard", href: "/admin/dashboard" },
    { label: "Classes & Events", href: "/admin/classes" },
    { label: "Announcements", href: "/admin/announcements" },
    { label: "Volunteers", href: "/admin/volunteers" },
    { label: "Donations", href: "/admin/donations" },
    { label: "Users / Staff", href: "/admin/viewusers" },
    { label: "Settings", href: "/admin/settings" },
];

function AdminLayout({ children }) {
    const { signOut } = useClerk();
    const currentPath = window.location.pathname.replace(/\/+$/, "");

    async function handleSignOut() {
        await signOut();
        window.location.assign("/");
    }

    return (
        <div className="admin-layout">
            <aside className="admin-sidebar">
                <p className="admin-sidebar__brand">Heal One World</p>
                <nav aria-label="Admin">
                    <ul className="admin-sidebar__nav">
                        {NAV_LINKS.map((link) => (
                            <li key={link.href}>
                                <a
                                    href={link.href}
                                    aria-current={currentPath === link.href ? "page" : undefined}
                                >
                                    {link.label}
                                </a>
                            </li>
                        ))}
                    </ul>
                </nav>
                <button type="button" className="admin-sidebar__logout" onClick={handleSignOut}>
                    Log out
                </button>
            </aside>
            <main className="admin-main">{children}</main>
        </div>
    );
}

export default AdminLayout;
